/// <summary>
/// CB731_LaserNetBundleTOMultithreadBatch.
/// Controller class for the order shipment bundling reporting job.
/// </summary>
class METOrderShipmentBundlingReportingJobController extends SysOperationServiceController
{
}

Method.Source:
/// <summary>
/// Constructs <c>METOrderShipmentBundlingReportingJobController</c>.
/// </summary>
/// <returns>
/// <c>METOrderShipmentBundlingReportingJobController</c>.
/// </returns>
public static METOrderShipmentBundlingReportingJobController construct()
{
    return new METOrderShipmentBundlingReportingJobController();
}

/// <summary>
/// Instantiates new object.
/// </summary>
void new()
{
    super(classStr(METOrderShipmentBundlingReportingJobService),
          methodStr(METOrderShipmentBundlingReportingJobService, process),
          SysOperationExecutionMode::Synchronous);
}

/// <summary>
/// Schedules job in batch.
/// </summary>
/// <param name = "_loadId">Load Id.</param>
/// <param name = "_shipmentId">Shipment Id.</param>
public static void sheduledInBatch(MetLoadId _loadId, MetShipmentId _shipmentId = '')
{
    METOrderShipmentBundlingReportingJobController controller;
    METOrderShipmentBundlingReportingJobContract contract;
    METThreadCount threadCount;

    controller = METOrderShipmentBundlingReportingJobController::construct();
    threadCount = WHSParameters::find().METFinalisationThreadCount;

    controller.parmShowDialog(false);
    controller.parmExecutionMode(SysOperationExecutionMode::ScheduledBatch);
    controller.parmDialogCaption(strFmt("@MET:OrderShipmentBundlingReportingJobForLoad", _loadId));

    contract = controller.getDataContractObject() as METOrderShipmentBundlingReportingJobContract;

    contract.parmLoadId(_loadId);
    contract.parmShipmentId(_shipmentId);
    contract.parmThreadCount(threadCount);

    controller.startOperation();
}

/// <summary>
/// Starts the process.
/// </summary>
/// <param name = "_args">
/// <c>Args</c>.
/// </param>
public static void main(Args _args)
{
    METOrderShipmentBundlingReportingJobController controller;

    controller = METOrderShipmentBundlingReportingJobController::construct();

    controller.startOperation();
}

/// <summary>
/// Description
/// </summary>
/// <returns>Default caption.</returns>
public ClassDescription defaultCaption()
{
    return "@MET:OrderShipmentBundlingReportingJob";
}
